// We use Verus to verify correctness of the rotation function.
use vstd::prelude::*;
verus! {
    /// rotate_right takes a non-empty vector of u32s and a non-negative rotation amount n,
    /// and returns a new vector which is the original vector rotated to the right by n.
    ///
    /// If len = list.len(), we let k = n % len and s = len - k.
    /// Then the result is list[s..len] ++ list[0..s].
    fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
        requires
            list.len() > 0,
        ensures
            new_list.len() == list.len(),
        ensures
            // for each index i in [0, len), new_list[i] = list[(s + i) % len]
            forall |i: usize|
                i < list.len()
                ==> new_list[i] == list[(list.len() - (n % list.len()) + i) % list.len()]
    {
        let len = list.len();
        let k = n % len;
        let s = len - k;

        let mut new_list: Vec<u32> = Vec::new();
        let mut i: usize = 0;

        // Build the rotated vector element by element.
        // Invariant: at iteration i we have pushed exactly i elements,
        // and for all j < i, new_list[j] == list[(s + j) % len].
        while i < len
            invariant i <= len
            invariant new_list.len() == i
            invariant forall |j: usize|
                j < i
                ==> new_list[j] == list[(s + j) % len]
            decreases len - i
        {
            // u32 is Copy, so indexing into list gives a value directly
            let x = list[(s + i) % len];
            new_list.push(x);
            i += 1;
        }

        new_list
    }
}